#pragma material(BlendMode = Additive, ShadingModel = Unlit, Backend = Graph)

uniform float3 Tint = float3(1.0, 1.0, 1.0);

/// @sampler Color
/// @default /Engine/EngineResources/DefaultTexture
uniform Texture2D Source;

export void M_RtHelperAndSwizzle(inout material m)
{
    float2 UV = UE.TextureCoordinate();
    float2 P = UV * 2.0 - 1.0;
    float4 Texel = Source.Sample(UV);

    m.EmissiveColor = Texel.xyz * Tint * saturate(1.0 - dot(P, P));
    m.Opacity = Texel.w;
}

#pragma layout(Node, Var = UV, X = -2336, Y = 560)
#pragma layout(Node, Var = P, X = -1696, Y = 752)
#pragma layout(Node, Var = Tint, X = -1408, Y = 480)
#pragma layout(Node, Var = Source, X = -1792, Y = 96)
#pragma layout(Node, Var = Texel, X = -1440, Y = 80)
